// Build the 30-day check-in email — sent to the new hire's personal email
// when the onboarder transitions to `thirty_day`. Inbound payload:
//   { onboarderId, template:'30-day-checkin', event, context: {
//     full_name, first_name, personal_email, role_title, team,
//     direct_supervisor, onboarding_lead
//   } }

const body = ($input.first().json.body ?? $input.first().json);
const ctx  = body.context || {};
const firstName        = ctx.first_name        || (ctx.full_name || 'there').split(' ')[0];
const toEmail          = ctx.personal_email    || body.to;
const onboardingLead   = ctx.onboarding_lead   || 'Erich';
const directSupervisor = ctx.direct_supervisor || 'your supervisor';
const roleTitle        = ctx.role_title        || '';

if (!toEmail) {
  throw new Error('No personal_email on context — cannot send 30-day check-in');
}

const subject = '30-day check-in | Romega Solutions';
const body_ = `Hi ${firstName},

You've been with Romega for about a month — congrats on making it through the first stretch! This is your 30-day check-in.

WE'D LOVE TO HEAR FROM YOU:
  • How is your first month going? Anything we should know?
  • Any blockers, missing tools, or training gaps?
  • Anything ${directSupervisor} or I can do to make week 5+ smoother?

WHAT TO EXPECT NEXT:
  • ${directSupervisor} will schedule a 30-day 1:1 with you this week.
  • Your 90-day probation review will follow at the 3-month mark.

Reply to this email with any thoughts, or bring them to your 1:1 — whichever feels easier.

Welcome aboard${roleTitle ? ` as ${roleTitle}` : ''} 🎉

Cheers,
${onboardingLead}
Onboarding Lead, Romega Solutions`;

return [{ json: { to: toEmail, subject, body: body_, onboarderId: body.onboarderId, template: '30-day-checkin' } }];
